    "bodyEn": "### 1. Historical & Analytical Overview\nImperialist rivalries and the assassination of Archduke Franz Ferdinand triggered World War I (1914-1918), ending with the Treaty of Versailles and the League of Nations.\n\n### 2. Core Board Highlights\n- **Key Point 1:** Causes of WWI: European alliances (Triple Alliance vs Triple Entente), aggressive nationalism, and colonial rivalry.\n- **Key Point 2:** Immediate trigger: Assassination of Austrian Archduke Franz Ferdinand at Sarajevo on June 28, 1914.\n- **Key Point 3:** Russian Revolution of 1917: Vladimir Lenin and Bolsheviks seized power, withdrawing Russia via the Treaty of Brest-Litovsk.\n- **Key Point 4:** Treaty of Versailles (1919): Harsh terms imposed on Germany, creating fertile ground for future conflicts.\n- **Key Point 5:** League of Nations established in 1920 to promote collective security, headquartered in Geneva.\n\n### 3. Public Exam Blueprint Significance\nThis unit holds critical weightage in Section A, 2-mark brief answers, 5-mark structured paragraphs, and map marking in the Tamil Nadu SSLC Social Science Board Exam.",
    "bodyTa": "### 1. பாட அறிமுகம் மற்றும் பகுப்பாய்வு\nஏகாதிபத்திய போட்டிகள் மற்றும் பிரான்ஸ் பெர்டினாண்ட் படுகொலை முதல் உலகப்போரை (1914-1918) தோற்றுவித்தன; வெர்செய்ல்ஸ் உடன்படிக்கை மற்றும் பன்னாட்டுச் சங்கம் உருவானது.\n\n### 2. முதன்மைப் பாடக் குறிப்புகள்\n- **முக்கியக் கருத்து 1:** முதல் உலகப்போருக்கான காரணங்கள்: ஐரோப்பிய முக்கூட்டு நாடுகள் மற்றும் நட்பு நாடுகள் ஒப்பந்தங்கள், தீவிர தேசியம்.\n- **முக்கியக் கருத்து 2:** உடனடிக் காரணம்: 1914 ஜூன் 28 அன்று சரஜீவோவில் ஆஸ்திரிய இளவரசர் பிரான்ஸ் பெர்டினாண்ட் படுகொலை.\n- **முக்கியக் கருத்து 3:** 1917 ரஷ்யப் புரட்சி: லெனின் தலைமையிலான போல்ஷிவிக்குகள் ஆட்சியைப் பிடித்து பிரெஸ்ட்-லிடோவ்ஸ்க் உடன்படிக்கை மூலம் போரிலிருந்து விலகினர்.\n- **முக்கியக் கருத்து 4:** வெர்செய்ல்ஸ் உடன்படிக்கை (1919): ஜெர்மனி மீது திணிக்கப்பட்ட கடுமையான நிபந்தனைகள்.\n- **முக்கியக் கருத்து 5:** பன்னாட்டுச் சங்கம்: 1920-ல் அமைதியை நிலைநாட்ட ஜெனிவாவைத் தலைமையிடமாகக் கொண்டு உருவாக்கப்பட்டது.\n\n### 3. பொதுத்தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் 1 மதிப்பெண், 2 மதிப்பெண், 5 மதிப்பெண் மற்றும் வரைபட வினாக்களில் இடம்பெறும் மிக முக்கியமான பாடமாகும்.",
    "rememberBoxes": [
      {
        "tipEn": "Map Marking Tip: For History and Geography, practice marking key ports, battle sites, mountain passes, and rivers on blank outline maps of India and Tamil Nadu.",
        "tipTa": "வரைபடக் குறிப்பு: வரலாறு மற்றும் புவியியல் பாடங்களில் முக்கிய வரலாற்று இடங்கள், துறைமுகங்கள், மலைகள் மற்றும் நதிகளை இந்தியா மற்றும் தமிழ்நாடு வரைபடத்தில் குறித்துப் பழகவும்."
      },
      {
        "tipEn": "Timeline Rule: For History 5-mark questions, always draw neat timeline charts with 5 events spanning 1900-1920 or 1920-1940 with uniform 5-year scale intervals.",
        "tipTa": "காலக்கோடு விதி: வரலாற்று 5-மதிப்பெண் வினாவிற்கு 1900-1920 அல்லது 1920-1940 வரையிலான காலக்கோட்டை 5 ஆண்டு இடைவெளியுடன் தெளிவாக வரையவும்."
      }
    ],
