    "titleEn": "Board Revision Notes: Geography Unit 7 - Human Geography of Tamil Nadu",
    "titleTa": "தேர்வு திருப்புதல் குறிப்புகள்: Geography அலகு 7 - தமிழ்நாடு - மானுடப் புவியியல்",
    "publishedAt": "23 Sep 2026",
    "publishedAtTa": "23 செப் 2026",
    "updatedAt": "23 Sep 2026",
    "updatedAtTa": "23 செப் 2026",
    "syllabusYear": "Samacheer Kalvi 2026–27",
    "syllabusYearTa": "சமச்சீர் கல்வி 2026–27",
    "reviewedBy": "TN SCERT Social Science Panel",
    "reviewedByRole": "State Board Senior Social Science Specialist",
    "reviewedAt": "23 Sep 2026",
    "reviewedAtTa": "23 செப் 2026",
    "status": "published",
    "version": "2.0.0",
    "changeNote": "Comprehensive bilingual notes with timelines, map points, constitutional articles, and board question answers.",
    "changeNoteTa": "காலக்கோடு, வரைபடம், அரசியல் சரத்துகள் மற்றும் விடைக்குறிப்புகளுடன் கூடிய முழுமையான இருமொழி பாடக் குறிப்புகள்.",
    "readTimeMinutes": 14,
    "bodyEn": "### 1. Historical & Analytical Overview\nDemographics, agriculture (Paddy in Thanjavur), industrial clusters, textile hubs, and environmental disaster preparedness in Tamil Nadu.\n\n### 2. Core Board Highlights\n- **Key Point 1:** Agriculture: Thanjavur is the 'Rice Bowl of Tamil Nadu'; Millets, pulses, sugarcane, and groundnuts widely grown.\n- **Key Point 2:** Water Resources: 17 river basins; 100% surface water exploited, relying heavily on groundwater and Northeast monsoon (48% rainfall).\n- **Key Point 3:** Industries: Textiles (Tiruppur 'Knitwear capital', Karur 'Home textile city'), Leather (Vellore/Ambur accounts for 37% of India's leather output).\n- **Key Point 4:** Transportation: Chennai Port (2nd largest container port), Tuticorin, and Ennore; massive road and rail density.\n- **Key Point 5:** Disaster Management: Vulnerability to cyclones, coastal erosion, tsunamis, and seasonal droughts addressed by TNDMA.\n\n### 3. Public Exam Blueprint Significance\nThis unit holds critical weightage in Section A, 2-mark brief answers, 5-mark structured paragraphs, and map marking in the Tamil Nadu SSLC Social Science Board Exam.",
    "bodyTa": "### 1. பாட அறிமுகம் மற்றும் பகுப்பாய்வு\nதமிழ்நாட்டின் மக்கள் தொகை, வேளாண்மை (தஞ்சை நெல்), தொழிற்துறை மையங்கள், ஜவுளி மற்றும் பேரிடர் மேலாண்மை.\n\n### 2. முதன்மைப் பாடக் குறிப்புகள்\n- **முக்கியக் கருத்து 1:** வேளாண்மை: தஞ்சாவூர் 'தமிழகத்தின் நெற்களஞ்சியம்'; கரும்பு, எண்ணெய்வித்துக்கள், பருப்பு வகைகள் பயிரிடப்படுகின்றன.\n- **முக்கியக் கருத்து 2:** நீர்வளம்: 17 நதி படுகைகள்; வடகிழக்கு பருவமழை 48% மழையைத் தந்து முதன்மை ஆதாரமாக விளங்குகிறது.\n- **முக்கியக் கருத்து 3:** தொழிலகங்கள்: ஜவுளி (திருப்பூர் பின்னலாடை, கரூர் வீட்டு ஜவுளி), தோல் தொழில் (வேலூர், ஆம்பூர் - இந்தியாவின் 37% தோல் உற்பத்தி).\n- **முக்கியக் கருத்து 4:** போக்குவரத்து: சென்னை, தூத்துக்குடி மற்றும் எண்ணூர் துறைமுகங்கள்; சிறந்த சாலை, ரயில் நெட்வொர்க்.\n- **முக்கியக் கருத்து 5:** பேரிடர் மேலாண்மை: புயல், சுனாமி மற்றும் வறட்சியை எதிர்கொள்ள தமிழ்நாடு பேரிடர் மேலாண்மை ஆணையம் (TNDMA) செயல்படுகிறது.\n\n### 3. பொதுத்தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் 1 மதிப்பெண், 2 மதிப்பெண், 5 மதிப்பெண் மற்றும் வரைபட வினாக்களில் இடம்பெறும் மிக முக்கியமான பாடமாகும்.",
