    "titleEn": "Board Revision Notes: Civics Unit 5 - India's International Relations",
    "titleTa": "தேர்வு திருப்புதல் குறிப்புகள்: Civics அலகு 5 - இந்தியாவின் சர்வதேச உறவுகள்",
    "publishedAt": "23 Sep 2026",
    "publishedAtTa": "23 செப் 2026",
    "updatedAt": "23 Sep 2026",
    "updatedAtTa": "23 செப் 2026",
    "syllabusYear": "Samacheer Kalvi 2026–27",
    "syllabusYearTa": "சமச்சீர் கல்வி 2026–27",
    "reviewedBy": "TN SCERT Social Science Panel",
    "reviewedByRole": "State Board Senior Social Science Specialist",
    "reviewedAt": "23 Sep 2026",
    "reviewedAtTa": "23 செப் 2026",
    "status": "published",
    "version": "2.0.0",
    "changeNote": "Comprehensive bilingual notes with timelines, map points, constitutional articles, and board question answers.",
    "changeNoteTa": "காலக்கோடு, வரைபடம், அரசியல் சரத்துகள் மற்றும் விடைக்குறிப்புகளுடன் கூடிய முழுமையான இருமொழி பாடக் குறிப்புகள்.",
    "readTimeMinutes": 14,
    "bodyEn": "### 1. Historical & Analytical Overview\nNeighbourhood First policy, SAARC, BRICS, and strategic bilateral partnerships with global powers.\n\n### 2. Core Board Highlights\n- **Key Point 1:** Neighbourhood First: Priority relationships with immediate neighbors (Nepal, Bhutan, Bangladesh, Sri Lanka, Maldives).\n- **Key Point 2:** SAARC (South Asian Association for Regional Cooperation): 8 member nations, secretariat in Kathmandu.\n- **Key Point 3:** BCIM and BIMSTEC: Fostering multi-sectoral technical and economic cooperation across the Bay of Bengal rim.\n- **Key Point 4:** BRICS (Brazil, Russia, India, China, South Africa): Alternate geopolitical economic cooperation and New Development Bank (NDB).\n- **Key Point 5:** Global partnerships: Strong bilateral ties with USA, Russia, Japan, France, and active presence in G20.\n\n### 3. Public Exam Blueprint Significance\nThis unit holds critical weightage in Section A, 2-mark brief answers, 5-mark structured paragraphs, and map marking in the Tamil Nadu SSLC Social Science Board Exam.",
    "bodyTa": "### 1. பாட அறிமுகம் மற்றும் பகுப்பாய்வு\nஅண்டை நாடுகளுக்கே முன்னுரிமை கொள்கை, சார்க் (SAARC), பிரிக்ஸ் (BRICS) மற்றும் சர்வதேச இருதரப்பு உறவுகள்.\n\n### 2. முதன்மைப் பாடக் குறிப்புகள்\n- **முக்கியக் கருத்து 1:** அண்டை நாடுகளுக்கே முன்னுரிமை: நேபாளம், பூடான், வங்கதேசம், இலங்கை, மாலத்தீவு ஆகியவற்றுடன் நட்புறவு.\n- **முக்கியக் கருத்து 2:** சார்க் (SAARC): 8 தெற்காசிய நாடுகள் கொண்ட அமைப்பு; செயலகம் காத்மாண்டுவில் உள்ளது.\n- **முக்கியக் கருத்து 3:** பிம்ஸ்டெக் (BIMSTEC): வங்காள விரிகுடா பல்துறை தொழில்நுட்ப பொருளாதார கூட்டுறவு அமைப்பு.\n- **முக்கியக் கருத்து 4:** பிரிக்ஸ் (BRICS): பிரேசில், ரஷ்யா, இந்தியா, சீனா, தென்னாப்பிரிக்கா இணைந்த பொருளாதார அமைப்பு.\n- **முக்கியக் கருத்து 5:** ஜி-20 (G20) தலைமை மற்றும் அமெரிக்கா, ரஷ்யா, ஜப்பான், பிரான்ஸ் உடனான கூட்டாண்மை.\n\n### 3. பொதுத்தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் 1 மதிப்பெண், 2 மதிப்பெண், 5 மதிப்பெண் மற்றும் வரைபட வினாக்களில் இடம்பெறும் மிக முக்கியமான பாடமாகும்.",
