    "reviewedBy": "TN SCERT Social Science Panel",
    "reviewedByRole": "State Board Senior Social Science Specialist",
    "reviewedAt": "23 Sep 2026",
    "reviewedAtTa": "23 செப் 2026",
    "status": "published",
    "version": "2.0.0",
    "changeNote": "Comprehensive bilingual notes with timelines, map points, constitutional articles, and board question answers.",
    "changeNoteTa": "காலக்கோடு, வரைபடம், அரசியல் சரத்துகள் மற்றும் விடைக்குறிப்புகளுடன் கூடிய முழுமையான இருமொழி பாடக் குறிப்புகள்.",
    "readTimeMinutes": 14,
    "bodyEn": "### 1. Historical & Analytical Overview\nIndustrialization pathways, engineering, automotive ('Detroit of Asia'), textiles, leather, and government agencies (SIPCOT, TIDCO, TANSIDCO).\n\n### 2. Core Board Highlights\n- **Key Point 1:** Industrial Cluster: Dense concentration of interconnected firms, suppliers, and institutions in a geographic region.\n- **Key Point 2:** Automobile Capital: Chennai is the 'Detroit of Asia', producing cars, commercial vehicles, railway coaches (ICF), and tanks (Avadi).\n- **Key Point 3:** Textile Triangle: Coimbatore, Tiruppur, and Erode generate major export revenues ('Textile Valley of Tamil Nadu').\n- **Key Point 4:** Leather Cluster: Ambur, Vaniyambadi, Ranipet, and Dindigul process high-grade leather shoes and garments.\n- **Key Point 5:** State Promotional Agencies: SIPCOT (State Industries Promotion Corporation of TN), TIDCO, TANSIDCO, and TIIC facilitate infrastructure.\n\n### 3. Public Exam Blueprint Significance\nThis unit holds critical weightage in Section A, 2-mark brief answers, 5-mark structured paragraphs, and map marking in the Tamil Nadu SSLC Social Science Board Exam.",
    "bodyTa": "### 1. பாட அறிமுகம் மற்றும் பகுப்பாய்வு\nதொழிற்துறை தொகுப்புகள், வாகன உற்பத்தி ('ஆசியாவின் டெட்ராய்ட்'), ஜவுளி, தோல் மற்றும் அரசு முகமைகள் (SIPCOT, TIDCO).\n\n### 2. முதன்மைப் பாடக் குறிப்புகள்\n- **முக்கியக் கருத்து 1:** தொழிற்துறை தொகுப்பு: ஒரு குறிப்பிட்ட பகுதியில் தொடர்புடைய நிறுவனங்கள் மற்றும் சேவை அமைப்புகளின் அடர்த்தியான குழுமம்.\n- **முக்கியக் கருத்து 2:** வாகன நகரம்: சென்னை 'ஆசியாவின் டெட்ராய்ட்' என அழைக்கப்படுகிறது (கார், பேருந்து, ரயில் பெட்டிகள் - ICF, ராணுவ பீரங்கி - ஆவடி).\n- **முக்கியக் கருத்து 3:** ஜவுளி பள்ளத்தாக்கு: கோயம்புத்தூர், திருப்பூர், ஈரோடு மண்டலம் பெரும் ஏற்றுமதி வருவாயை ஈட்டுகிறது.\n- **முக்கியக் கருத்து 4:** தோல் தொழில்: ஆம்பூர், வாணியம்பாடி, ராணிப்பேட்டை மற்றும் திண்டுக்கல்.\n- **முக்கியக் கருத்து 5:** தொழில் வளர்ச்சி முகமைகள்: சிப்காட் (SIPCOT), டிட்கோ (TIDCO), டான்சிட்கோ (TANSIDCO) தொழிற்பேட்டைகளை உருவாக்குகின்றன.\n\n### 3. பொதுத்தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் 1 மதிப்பெண், 2 மதிப்பெண், 5 மதிப்பெண் மற்றும் வரைபட வினாக்களில் இடம்பெறும் மிக முக்கியமான பாடமாகும்.",
