    "titleEn": "Concept & Map Flowchart: India - Location, Relief and Drainage",
    "titleTa": "கருத்து மற்றும் வரைபட விளக்கப்படம்: இந்தியா - அமைவிடம், நிலத்தோற்றம் மற்றும் வடிகாலமைப்பு",
    "descriptionEn": "Interactive structural concept and geographical map flowchart for India - Location, Relief and Drainage.",
    "descriptionTa": "இந்தியா - அமைவிடம், நிலத்தோற்றம் மற்றும் வடிகாலமைப்பு பாடத்தின் முக்கிய கருத்துகள், வரைபடக் குறிப்புகள் மற்றும் நிகழ்வுகளை விளக்கும் வரைபடம்.",
